<script setup lang="ts">
import { Box, Cpu, Plus, RefreshCw, ServerCog } from 'lucide-vue-next'
import { computed, reactive, ref } from 'vue'
import { storeToRefs } from 'pinia'
import DashboardPageHeader from '@/components/shared/DashboardPageHeader.vue'
import AppButton from '@/components/ui/AppButton.vue'
import AppBadge from '@/components/ui/AppBadge.vue'
import StatusDot from '@/components/ui/StatusDot.vue'
import { useWorkspaceStore } from '@/stores/workspace'

const store = useWorkspaceStore()
const { servers } = storeToRefs(store)
const onlineCount = computed(() => servers.value.filter(server => server.status !== 'offline').length)
const gpuCount = computed(() => servers.value.reduce((count, server) => count + server.gpus.length, 0))
const containerCount = computed(() => servers.value.reduce((count, server) => count + server.containers, 0))
async function refresh() { await store.refreshServers() }
const showAdd = ref(false)
const notice = ref('')
const draft = reactive({ name: '', hostname: '', ip: '', description: '', location: '', os: 'Ubuntu 24.04', provider: 'mock', capabilities: 'SSH, Docker' })
function resetDraft() { Object.assign(draft, { name: '', hostname: '', ip: '', description: '', location: '', os: 'Ubuntu 24.04', provider: 'mock', capabilities: 'SSH, Docker' }) }
async function addServer() {
  if (!draft.name.trim()) { notice.value = 'Enter a server name.'; return }
  const created = await store.createServer({ name: draft.name.trim(), hostname: draft.hostname.trim(), ip: draft.ip.trim() || null, description: draft.description.trim(), location: draft.location.trim(), os: draft.os.trim(), provider: draft.provider, status: 'offline', capabilities: draft.capabilities.split(',').map(item => item.trim()).filter(Boolean), cpu: 0, memory: { used: 0, total: 0 }, disk: { used: 0, total: 0 }, gpus: [], containers: 0, enabled: true })
  if (!created) { notice.value = 'Server could not be saved. Check the workspace connection and try again.'; return }
  showAdd.value = false; resetDraft(); notice.value = 'Server added to the workspace inventory.'
}
</script>
<template><div><DashboardPageHeader title="Servers" description="A capability-aware view of the machines behind your research."><AppButton variant="secondary" @click="refresh"><RefreshCw :size="15" /> Refresh status</AppButton><AppButton @click="showAdd = !showAdd"><Plus :size="15" /> Add server</AppButton></DashboardPageHeader><p v-if="notice" class="feedback" role="status">{{ notice }}</p><form v-if="showAdd" class="record-editor new-server-form" @submit.prevent="addServer"><div class="editor-heading"><div><h2>Add server</h2><p class="muted-copy">Store inventory metadata now; live SSH, Docker and 3x-ui connectors remain explicit integrations.</p></div><AppButton type="submit">Save server</AppButton></div><div class="field-grid"><label>Name<input v-model="draft.name" required /></label><label>Hostname<input v-model="draft.hostname" /></label><label>IP address<input v-model="draft.ip" placeholder="10.0.0.12" /></label><label>Location<input v-model="draft.location" /></label><label>Operating system<input v-model="draft.os" /></label><label>Provider<select v-model="draft.provider"><option value="mock">Mock snapshot</option><option value="ssh">SSH connector</option><option value="xui">3x-ui connector</option></select></label></div><label>Description<textarea v-model="draft.description" rows="2" /></label><label>Capabilities <input v-model="draft.capabilities" placeholder="SSH, Docker, NVIDIA_GPU" /><small class="muted-copy">Comma-separated labels used by the inventory view.</small></label><div class="editor-actions"><AppButton type="submit">Save server</AppButton><button type="button" @click="showAdd = false">Cancel</button></div></form><section class="fleet-summary"><div><span>Fleet</span><strong>{{ servers.length }}</strong><small>machines</small></div><div><span>Availability</span><strong>{{ onlineCount }} / {{ servers.length }}</strong><small>reachable</small></div><div><span>GPU capacity</span><strong>{{ gpuCount }}</strong><small>NVIDIA GPUs</small></div><div><span>Containers</span><strong>{{ containerCount }}</strong><small>running</small></div></section><section class="server-grid"><article v-for="server in servers" :key="server.id" class="server-card" :class="{ 'is-offline': server.status === 'offline' }"><header><div class="server-icon"><ServerCog :size="19" /></div><div><h2>{{ server.name }}</h2><p>{{ server.description }}</p></div><div class="server-status"><StatusDot :status="server.status" /><span>{{ server.status }}</span></div></header><div class="server-meta"><span>{{ server.os }}</span><span>{{ server.location }}</span><span>{{ server.ip || 'IP not set' }}</span></div><template v-if="server.status !== 'offline'"><div class="resource-bars"><div><span>CPU <b>{{ server.cpu }}%</b></span><i><em :style="{ width: `${server.cpu}%` }" /></i></div><div><span>RAM <b>{{ server.memory.used }} / {{ server.memory.total }} GB</b></span><i><em :style="{ width: `${server.memory.total ? server.memory.used / server.memory.total * 100 : 0}%` }" /></i></div><div><span>Disk <b>{{ server.disk.used }} / {{ server.disk.total }} TB</b></span><i><em :style="{ width: `${server.disk.total ? server.disk.used / server.disk.total * 100 : 0}%` }" /></i></div></div><div v-if="server.gpus.length" class="gpu-strip"><div class="gpu-heading"><span><Cpu :size="14" /> {{ server.gpus[0].name }} × {{ server.gpus.length }}</span><small>GPU utilization</small></div><div class="gpu-values"><span v-for="(gpu, index) in server.gpus" :key="index"><b>{{ gpu.utilization }}</b><small>%</small></span></div></div><div v-else class="no-gpu"><Cpu :size="15" /><span>No GPU capability</span></div></template><div v-else class="offline-state"><p>Last seen {{ server.lastSeen || 'never' }}.</p><button @click="refresh">Retry connection</button></div><footer><div class="capability-list"><AppBadge v-for="capability in server.capabilities" :key="capability">{{ capability.replace('_', ' ') }}</AppBadge></div><div><span><Box :size="14" /> {{ server.containers }} running</span><span>Uptime {{ server.uptime }}</span></div></footer></article></section></div></template>
